// carries it). Every caller passes the zone: this file never reads env or config, so the "which zone" decision stays with the caller.

// Fleet default; callers may still choose any IANA zone explicitly.
export const DEFAULT_ZONE = 'America/New_York';

// DateTimeFormatter construction is expensive (locale-data resolution) and these helpers run per row in hot loops, so formatters
// are cached per locale+options. The cache stays tiny: one entry per distinct (locale, timezone, options) combination in use.
/** @type {Map<string, DateTimeFormatter>} */
